template.script:
/*  */
(function() {
    function initLoginInteractive3D() {
        const canvas = document.getElementById('insilosLoginDigitalTwinCanvas');
        const viewport = document.getElementById('insilosLoginDigitalTwinViewport');
        if (!canvas || !viewport) return;

        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = canvas.width = viewport.clientWidth || 380;
        let height = canvas.height = viewport.clientHeight || 220;

        // Camera rotation angles
        let rotX = 0.28, rotY = -0.32, rotZ = 0;
        let targetRotX = 0.28, targetRotY = -0.32;
        let isDragging = false, lastMouseX = 0, lastMouseY = 0;
        let autoOrbit = true;
        let showDataFlow = true;

        window.addEventListener('resize', function() {
            if (!viewport || !canvas) return;
            width = canvas.width = viewport.clientWidth || 380;
            height = canvas.height = viewport.clientHeight || 220;
        });

        viewport.addEventListener('mousedown', function(e) {
            isDragging = true;
            autoOrbit = false;
            lastMouseX = e.clientX;
            lastMouseY = e.clientY;
            viewport.style.cursor = 'grabbing';
        });

        window.addEventListener('mousemove', function(e) {
            if (isDragging) {
                const dx = e.clientX - lastMouseX;
                const dy = e.clientY - lastMouseY;
                targetRotY += dx * 0.012;
                targetRotX += dy * 0.012;
                // Clamp vertical tilt to avoid flipping
                targetRotX = Math.max(-0.6, Math.min(0.8, targetRotX));
                lastMouseX = e.clientX;
                lastMouseY = e.clientY;
            }
        });

        window.addEventListener('mouseup', function() {
            isDragging = false;
            if (viewport) viewport.style.cursor = 'grab';
        });

        // HUD Toggle Buttons
        const btnSilos = document.getElementById('btnModeSilos');
        const btnFlow = document.getElementById('btnModeFlow');
        const btnOrbit = document.getElementById('btnModeOrbit');

        if (btnSilos) {
            btnSilos.addEventListener('click', function() {
                targetRotX = 0.28;
                targetRotY = -0.32;
                btnSilos.classList.add('border-warning', 'text-warning');
            });
        }
        if (btnFlow) {
            btnFlow.addEventListener('click', function() {
                showDataFlow = !showDataFlow;
                if (showDataFlow) {
                    btnFlow.classList.add('border-cyan', 'text-cyan');
                    btnFlow.classList.remove('text-white-50');
                } else {
                    btnFlow.classList.remove('border-cyan', 'text-cyan');
                    btnFlow.classList.add('text-white-50');
                }
            });
        }
        if (btnOrbit) {
            btnOrbit.addEventListener('click', function() {
                autoOrbit = !autoOrbit;
                if (autoOrbit) {
                    btnOrbit.classList.add('border-warning', 'text-warning');
                    btnOrbit.classList.remove('text-white-50');
                } else {
                    btnOrbit.classList.remove('border-warning', 'text-warning');
                    btnOrbit.classList.add('text-white-50');
                }
            });
        }

        // =========================================================================
        // 3D GEOMETRY DEFINITION: THE INSILOS ICON
        // Three Cylindrical Silos + Diagonal Cybernetic Data Bridge
        // =========================================================================
        // Silo 0: Left Column (MES / Shop Floor) - 5 stacked discs + top cap
        // Silo 1: Center Column (SCM / Logistics) - 5 stacked discs + top cap (elevated)
        // Silo 2: Right Column (FI/CO / Finance) - 5 stacked discs + top cap
        const silos = [
            {
                id: 'mes',
                label: 'MES',
                name: 'Sản Xuất',
                x: -66,
                rx: 23,
                rz: 14,
                levels: [-44, -22, 0, 22, 44],
                capY: 57,
                baseColor: '#FF9800',
                topColor: '#FFB74D',
                edgeColor: '#E65100'
            },
            {
                id: 'scm',
                label: 'SCM',
                name: 'Chuỗi Cung Ứng',
                x: 0,
                rx: 20,
                rz: 13,
                levels: [-34, -12, 10, 32, 54],
                capY: 67,
                baseColor: '#FFA000',
                topColor: '#FFE082',
                edgeColor: '#F57C00'
            },
            {
                id: 'fico',
                label: 'FI/CO',
                name: 'Tài Chính',
                x: +66,
                rx: 23,
                rz: 14,
                levels: [-40, -18, 4, 26, 48],
                capY: 61,
                baseColor: '#FF8F00',
                topColor: '#FFCA28',
                edgeColor: '#EF6C00'
            }
        ];

        // Diagonal Data Bridge Connecting Silo 1 and Silo 2 (Exactly matching Insilos logo mask 30/31)
        // And secondary bridge linking Silo 0 and Silo 1
        const bridges = [
            { from: { x: 0, y: 10, z: 0 }, to: { x: 66, y: -18, z: 0 }, color: '#00f0ff' },
            { from: { x: -66, y: 0, z: 0 }, to: { x: 0, y: 10, z: 0 }, color: '#ffb74d' }
        ];

        let time = 0;
        let animFrame;

        function projectPoint(x, y, z, cosX, sinX, cosY, sinY, cx, cy, fov) {
            // Rotate Y
            const x1 = x * cosY - z * sinY;
            const z1 = z * cosY + x * sinY;
            // Rotate X
            const y2 = y * cosX - z1 * sinX;
            const z2 = z1 * cosX + y * sinX + 250;

            const scale = fov / (z2 || 1);
            return {
                x: cx + x1 * scale,
                y: cy - y2 * scale,
                z: z2,
                scale: scale
            };
        }

        function render() {
            time += 0.025;
            rotX += (targetRotX - rotX) * 0.08;
            rotY += (targetRotY - rotY) * 0.08;
            if (autoOrbit && !isDragging) {
                targetRotY += 0.007;
            }

            ctx.clearRect(0, 0, width, height);

            const cx = width / 2;
            const cy = height / 2 - 2;
            const fov = 320;

            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);

            // 1. Draw Horizon Hologram Ring under the 3 Silos
            const centerGround = projectPoint(0, -68, 0, cosX, sinX, cosY, sinY, cx, cy, fov);
            ctx.beginPath();
            ctx.ellipse(centerGround.x, centerGround.y, 110 * centerGround.scale, 35 * centerGround.scale, 0, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255, 152, 0, 0.22)';
            ctx.lineWidth = 1.2;
            ctx.stroke();

            ctx.beginPath();
            ctx.ellipse(centerGround.x, centerGround.y, 65 * centerGround.scale, 20 * centerGround.scale, 0, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(0, 240, 255, 0.28)';
            ctx.lineWidth = 1;
            ctx.stroke();

            // 2. Collect All Renderable 3D Discs for Depth Sorting
            const renderItems = [];

            silos.forEach(function(silo, sIdx) {
                silo.levels.forEach(function(lvlY, dIdx) {
                    const diskHeight = 6.5;
                    const centerProj = projectPoint(silo.x, lvlY, 0, cosX, sinX, cosY, sinY, cx, cy, fov);
                    renderItems.push({
                        type: 'disc',
                        siloIndex: sIdx,
                        silo: silo,
                        lvlY: lvlY,
                        height: diskHeight,
                        center: centerProj,
                        z: centerProj.z
                    });
                });

                // Top Dome Cap for each Silo (characteristic of Insilos brand)
                const capProj = projectPoint(silo.x, silo.capY, 0, cosX, sinX, cosY, sinY, cx, cy, fov);
                renderItems.push({
                    type: 'cap',
                    siloIndex: sIdx,
                    silo: silo,
                    center: capProj,
                    z: capProj.z
                });
            });

            // Add Data Bridges to render items
            bridges.forEach(function(br, bIdx) {
                const pA = projectPoint(br.from.x, br.from.y, br.from.z, cosX, sinX, cosY, sinY, cx, cy, fov);
                const pB = projectPoint(br.to.x, br.to.y, br.to.z, cosX, sinX, cosY, sinY, cx, cy, fov);
                renderItems.push({
                    type: 'bridge',
                    bridge: br,
                    pA: pA,
                    pB: pB,
                    z: (pA.z + pB.z) / 2
                });
            });

            // Sort by depth (back to front: highest Z first)
            renderItems.sort(function(a, b) {
                return b.z - a.z;
            });

            // 3. Render All Sorted Items
            renderItems.forEach(function(item) {
                if (item.type === 'bridge') {
                    // Draw Cybernetic Diagonal Bridge
                    const pA = item.pA;
                    const pB = item.pB;

                    // Bridge Core Glow Beam
                    ctx.beginPath();
                    ctx.moveTo(pA.x, pA.y);
                    ctx.lineTo(pB.x, pB.y);
                    ctx.strokeStyle = item.bridge.color;
                    ctx.lineWidth = Math.max(1.8, 2.8 * pA.scale);
                    ctx.shadowColor = item.bridge.color;
                    ctx.shadowBlur = 10;
                    ctx.stroke();

                    // Streaming Data Packets along the Bridge
                    if (showDataFlow) {
                        const packetCount = 4;
                        for (let k = 0; k < packetCount; k++) {
                            const progress = ((time * 0.9 + k / packetCount) % 1);
                            const px = pA.x + (pB.x - pA.x) * progress;
                            const py = pA.y + (pB.y - pA.y) * progress;
                            const pz = pA.z + (pB.z - pA.z) * progress;
                            const pscale = fov / (pz || 1);

                            ctx.beginPath();
                            ctx.arc(px, py, Math.max(2.2, 3.8 * pscale), 0, Math.PI * 2);
                            ctx.fillStyle = (k % 2 === 0) ? '#ffffff' : '#00f0ff';
                            ctx.shadowColor = '#00f0ff';
                            ctx.shadowBlur = 12;
                            ctx.fill();
                        }
                    }
                    ctx.shadowBlur = 0;
                } else if (item.type === 'disc') {
                    const silo = item.silo;
                    const lvlY = item.lvlY;
                    const h = item.height;

                    // 3D Ellipse points for top and bottom faces of disk
                    const steps = 18;
                    const topPts = [];
                    const botPts = [];

                    for (let i = 0; i <= steps; i++) {
                        const th = (i / steps) * Math.PI * 2;
                        const localX = silo.x + silo.rx * Math.cos(th);
                        const localZ = silo.rz * Math.sin(th);
                        topPts.push(projectPoint(localX, lvlY + h / 2, localZ, cosX, sinX, cosY, sinY, cx, cy, fov));
                        botPts.push(projectPoint(localX, lvlY - h / 2, localZ, cosX, sinX, cosY, sinY, cx, cy, fov));
                    }

                    // Draw Disc Cylinder Rim / Side Body
                    ctx.beginPath();
                    ctx.moveTo(topPts[0].x, topPts[0].y);
                    for (let i = 1; i <= steps; i++) {
                        ctx.lineTo(topPts[i].x, topPts[i].y);
                    }
                    for (let i = steps; i >= 0; i--) {
                        ctx.lineTo(botPts[i].x, botPts[i].y);
                    }
                    ctx.closePath();

                    const sideGrad = ctx.createLinearGradient(
                        topPts[0].x, topPts[0].y,
                        topPts[Math.floor(steps / 2)].x, topPts[Math.floor(steps / 2)].y
                    );
                    sideGrad.addColorStop(0, silo.edgeColor);
                    sideGrad.addColorStop(0.5, silo.baseColor);
                    sideGrad.addColorStop(1, silo.edgeColor);

                    ctx.fillStyle = sideGrad;
                    ctx.fill();
                    ctx.strokeStyle = 'rgba(255, 200, 50, 0.4)';
                    ctx.lineWidth = 0.8;
                    ctx.stroke();

                    // Draw Disc Top Face
                    ctx.beginPath();
                    ctx.moveTo(topPts[0].x, topPts[0].y);
                    for (let i = 1; i <= steps; i++) {
                        ctx.lineTo(topPts[i].x, topPts[i].y);
                    }
                    ctx.closePath();

                    const topGrad = ctx.createLinearGradient(
                        topPts[0].x, topPts[0].y,
                        topPts[Math.floor(steps / 2)].x, topPts[Math.floor(steps / 2)].y
                    );
                    topGrad.addColorStop(0, silo.topColor);
                    topGrad.addColorStop(0.6, silo.baseColor);
                    topGrad.addColorStop(1, silo.edgeColor);

                    ctx.fillStyle = topGrad;
                    ctx.shadowColor = silo.baseColor;
                    ctx.shadowBlur = 6;
                    ctx.fill();
                    ctx.shadowBlur = 0;

                    ctx.strokeStyle = '#fff2a8';
                    ctx.lineWidth = 1;
                    ctx.stroke();

                } else if (item.type === 'cap') {
                    // Top Dome Cap for the Silo
                    const silo = item.silo;
                    const topPts = [];
                    const steps = 18;
                    for (let i = 0; i <= steps; i++) {
                        const th = (i / steps) * Math.PI * 2;
                        const localX = silo.x + silo.rx * 0.95 * Math.cos(th);
                        const localZ = silo.rz * 0.95 * Math.sin(th);
                        topPts.push(projectPoint(localX, silo.capY, localZ, cosX, sinX, cosY, sinY, cx, cy, fov));
                    }

                    ctx.beginPath();
                    ctx.moveTo(topPts[0].x, topPts[0].y);
                    for (let i = 1; i <= steps; i++) {
                        ctx.lineTo(topPts[i].x, topPts[i].y);
                    }
                    ctx.closePath();
                    ctx.fillStyle = '#FFE082';
                    ctx.shadowColor = '#FF9800';
                    ctx.shadowBlur = 10;
                    ctx.fill();
                    ctx.shadowBlur = 0;

                    // Floating 3D Micro-Badge Tag above Silo
                    const tagProj = projectPoint(silo.x, silo.capY + 16, 0, cosX, sinX, cosY, sinY, cx, cy, fov);
                    ctx.save();
                    ctx.font = 'bold 9.5px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    const tagText = silo.label;
                    const textW = ctx.measureText(tagText).width;

                    ctx.fillStyle = 'rgba(7, 15, 30, 0.88)';
                    ctx.strokeStyle = '#00f0ff';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.roundRect(tagProj.x - textW / 2 - 5, tagProj.y - 7, textW + 10, 14, 3);
                    ctx.fill();
                    ctx.stroke();

                    ctx.fillStyle = '#00f0ff';
                    ctx.fillText(tagText, tagProj.x, tagProj.y);
                    ctx.restore();
                }
            });

            animFrame = requestAnimationFrame(render);
        }

        render();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initLoginInteractive3D);
    } else {
        initLoginInteractive3D();
    }
})();
/*  */
